<h1><?= e($title) ?></h1><?php if(!empty($_SESSION['flash'])): ?><p class="notice"><?= e($_SESSION['flash']); unset($_SESSION['flash']); ?></p><?php endif; ?>
<form method="post" action="/admin/<?= e($collection) ?>/save" class="admin-form"><?php foreach($fields as $field): ?><label><?= e(ucwords(str_replace('_',' ',$field))) ?><input name="<?= e($field) ?>"></label><?php endforeach; ?><button>Save <?= e(rtrim($title,'s')) ?></button></form>
<table><tr><?php foreach($fields as $field): ?><th><?= e(ucwords(str_replace('_',' ',$field))) ?></th><?php endforeach; ?><th>Action</th></tr><?php foreach($items as $item): ?><tr><?php foreach($fields as $field): ?><td><?= e(is_array($item[$field]??null)?implode(', ',$item[$field]):(string)($item[$field]??'')) ?></td><?php endforeach; ?><td><form method="post" action="/admin/<?= e($collection) ?>/delete"><input type="hidden" name="id" value="<?= e($item['id']) ?>"><button>Delete</button></form></td></tr><?php endforeach; ?></table>
